/**
 * Magic title used for the per-directory README note. WerSu keeps this note
 * invisible to the directory listing and uses its body to drive the
 * directory's display name, description, and image. See `DirectoryEdit`.
 */
export const README_NOTE_TITLE = "README.md";

/**
 * Structure version of the README generated by this client. Bump this
 * whenever the layout of the auto-generated header changes so existing
 * READMEs can be migrated the next time they are written.
 */
export const README_STRUCTURE_VERSION = 2;

export const README_VERSION_MARKER = `<!-- wersu-readme-structure-version: ${README_STRUCTURE_VERSION} -->`;

const README_VERSION_PATTERN =
  /<!--\s*wersu-readme-structure-version:\s*(\d+)\s*-->/i;
const README_VERSION_PATTERN_GLOBAL =
  /<!--\s*wersu-readme-structure-version:\s*(\d+)\s*-->/gi;

/**
 * Separates the auto-generated header from the user-authored body. The
 * header is regenerated on every directory save; manual edits below the
 * sentinel are preserved.
 */
export const README_SENTINEL = [
  "> [!CAUTION]",
  "> only change content below this info; the header is used by WerSu",
  README_VERSION_MARKER,
].join("\n");

/**
 * Older sentinels emitted by previous versions. Kept so existing READMEs
 * still round-trip and so any duplicates left behind below the body are
 * stripped on the next save.
 */
const LEGACY_README_SENTINELS = [
  // v1: Markdown heading sentinel.
  "# do not change, this is autogenerated and used by WerSu",
  // v2 without the version marker: the caution block shipped before
  // versioning was added.
  [
    "> [!CAUTION]",
    "> only change content below this info; the header is used by WerSu",
  ].join("\n"),
];

const README_SENTINELS = [README_SENTINEL, ...LEGACY_README_SENTINELS];

/** Index of the first sentinel in `content`, or -1 when there is none. */
const firstSentinelIndex = (content: string): number => {
  let index = -1;
  for (const sentinel of README_SENTINELS) {
    const candidate = content.indexOf(sentinel);
    if (candidate !== -1 && (index === -1 || candidate < index)) {
      index = candidate;
    }
  }
  return index;
};

/** Removes every sentinel occurrence, including ones duplicated below the body. */
const stripSentinels = (value: string): string => {
  let result = value;
  for (const sentinel of README_SENTINELS) {
    result = result.split(sentinel).join("");
  }
  return result.replace(README_VERSION_PATTERN_GLOBAL, "").trim();
};

/**
 * Returns the README structure version. Unversioned content is inferred
 * from its sentinel: the original heading-based structure is v1, and the
 * caution-block structure without a version marker is v2.
 */
export function getReadmeStructureVersion(
  content: string | undefined,
): number {
  if (!content) {
    return 0;
  }
  const version = README_VERSION_PATTERN.exec(content);
  if (version) {
    return Number(version[1]);
  }
  if (content.includes(LEGACY_README_SENTINELS[0])) {
    return 1;
  }
  if (content.includes(LEGACY_README_SENTINELS[1])) {
    return README_STRUCTURE_VERSION;
  }
  return 0;
}

export interface ReadmeHeader {
  name: string;
  description?: string;
  imageUrl?: string;
}

/**
 * Builds the README note body for a directory. The shape is:
 *
 *     # <name>
 *
 *     ![bookImage](<imageUrl>)
 *
 *     > [!CAUTION]
 *     > only change content below this info; the header is used by WerSu
 *     <!-- wersu-readme-structure-version: 2 -->
 *
 *     <description / body>
 *
 * The image is omitted when absent. The description seeds the body when no
 * user-authored body exists yet; after that the body below the sentinel is
 * owned by the user. The sentinel is always present, and any sentinel already
 * present in `body` is stripped so duplicate "do not change" blocks can never
 * accumulate below the user content.
 */
export function serializeReadme(
  header: ReadmeHeader,
  body: string = "",
): string {
  const sections: string[] = [];

  sections.push(`# ${header.name}`);
  sections.push("");

  if (header.imageUrl && header.imageUrl.trim().length > 0) {
    sections.push(`![bookImage](${header.imageUrl.trim()})`);
    sections.push("");
  }

  sections.push(README_SENTINEL);

  const cleanBody = stripSentinels(body);
  const description = header.description?.trim() ?? "";
  const content = cleanBody.length > 0 ? cleanBody : description;
  if (content.length > 0) {
    sections.push("");
    sections.push(content);
  }

  return sections.join("\n");
}

/**
 * Returns the user-authored body of a README: everything below the first
 * sentinel, with any sentinel blocks that were previously appended below
 * the content removed.
 */
export function extractReadmeBody(content: string | undefined): string {
  if (!content) {
    return "";
  }
  const sentinelIndex = firstSentinelIndex(content);
  if (sentinelIndex === -1) {
    return "";
  }
  return stripSentinels(content.slice(sentinelIndex));
}

/**
 * Rewrites a README into the current structure version. The directory owns
 * the header, so only the user-authored body is carried across.
 */
export function migrateReadme(
  content: string | undefined,
  header: ReadmeHeader,
): string {
  return serializeReadme(header, extractReadmeBody(content));
}

/**
 * Returns a short, single-line preview of the auto-generated header of a
 * README body. Drops everything below the sentinel (the user-authored
 * section) and clips to `maxLength` characters. Used by the image upload
 * modal to give the user a hint of what they're attaching to.
 */
export function getReadmePreview(
  content: string | undefined,
  maxLength = 300,
): string {
  if (!content) {
    return "";
  }
  const sentinelIndex = firstSentinelIndex(content);
  const header =
    sentinelIndex === -1 ? content : content.slice(0, sentinelIndex);
  const collapsed = header.replace(/\s+/g, " ").trim();
  if (collapsed.length <= maxLength) {
    return collapsed;
  }
  return `${collapsed.slice(0, maxLength).trimEnd()}…`;
}
